PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE crawl_history (
    browser_id INTEGER,
    visit_id INTEGER,
    command TEXT,
    arguments TEXT,
    retry_number INTEGER,
    command_status TEXT,
    error TEXT,
    traceback TEXT,
    duration INTEGER,
    dtg DATETIME DEFAULT (CURRENT_TIMESTAMP),
    FOREIGN KEY(browser_id) REFERENCES crawl(browser_id));
COMMIT;
